const THEME_KEY='adcraft-theme';
const readTheme=()=>document.documentElement.getAttribute('data-theme')==='dark'?'dark':'light';
const applyTheme=(t)=>{
  const theme=t==='dark'?'dark':'light';
  document.documentElement.setAttribute('data-theme',theme);
  try{localStorage.setItem(THEME_KEY,theme)}catch(e){}
  const meta=document.querySelector('meta[name="theme-color"]');
  if(meta)meta.setAttribute('content',theme==='dark'?'#14130f':'#f8f7f3');
  document.querySelectorAll('[data-theme-toggle]').forEach(b=>{
    b.setAttribute('aria-label',theme==='dark'?'Switch to light mode':'Switch to dark mode');
    b.setAttribute('aria-pressed',theme==='dark'?'true':'false');
  });
};
const bindTheme=()=>{
  document.querySelectorAll('[data-theme-toggle]').forEach(b=>{
    b.onclick=()=>applyTheme(readTheme()==='dark'?'light':'dark');
  });
  applyTheme(readTheme());
};
