document.fonts.ready.then(() => {
  if (location.hash) document.getElementById(location.hash.slice(1))?.scrollIntoView({ behavior: 'instant' });
});
(function smoothScroll(){
  const reduce=window.matchMedia('(prefers-reduced-motion: reduce)');
  const coarse=window.matchMedia('(pointer: coarse)');
  if(reduce.matches||coarse.matches)return;
  document.documentElement.style.scrollBehavior='auto';
  let current=window.scrollY,target=window.scrollY,running=false;
  const ease=0.16;
  const maxY=()=>Math.max(0,document.documentElement.scrollHeight-innerHeight);
  const nested=(node)=>{
    let el=node instanceof Element?node:node.parentElement;
    while(el&&el!==document.body){
      const oy=getComputedStyle(el).overflowY;
      if((oy==='auto'||oy==='scroll')&&el.scrollHeight>el.clientHeight+1)return true;
      el=el.parentElement;
    }
    return false;
  };
  const start=()=>{
    if(running)return;
    running=true;
    const tick=()=>{
      target=Math.max(0,Math.min(maxY(),target));
      current+=(target-current)*ease;
      if(Math.abs(target-current)<0.45){
        current=target;
        scrollTo(0,current);
        running=false;
        return;
      }
      scrollTo(0,current);
      requestAnimationFrame(tick);
    };
    requestAnimationFrame(tick);
  };
  window.addEventListener('wheel',e=>{
    if(e.defaultPrevented||e.ctrlKey||nested(e.target))return;
    e.preventDefault();
    target=Math.max(0,Math.min(maxY(),target+e.deltaY));
    start();
  },{passive:false});
  window.addEventListener('scroll',()=>{if(!running)current=target=window.scrollY},{passive:true});
  window.addEventListener('adcraft:scroll',e=>{
    target=Math.max(0,Math.min(maxY(),Number(e.detail)||0));
    start();
  });
  document.addEventListener('click',e=>{
    const a=e.target.closest('a[href^="#"]');
    if(!a)return;
    const id=a.getAttribute('href').slice(1);
    const el=id&&document.getElementById(id);
    if(!el)return;
    e.preventDefault();
    window.dispatchEvent(new CustomEvent('adcraft:scroll',{detail:el.getBoundingClientRect().top+window.scrollY-80}));
  });
})();
